import type { DealRecord } from "./types";
import { detailPath } from "./ui/shared";

const STATIC_PATHS = ["/", "/deals", "/ai-tools", "/cloud"];

function xmlEscape(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/** robots.txt is generated by the worker so crawlers see Allow and Sitemap. */
export function robotsTxt(origin: string): string {
  const base = origin.trim().replace(/\/+$/, "");
  return [
    "# Deal Hunter",
    "User-agent: *",
    "Allow: /",
    `Sitemap: ${base}/sitemap.xml`,
    "",
  ].join("\n");
}

/** Static routes plus active deals. Archived rows stay out of the sitemap. */
export function sitemapXml(origin: string, deals: DealRecord[]): string {
  const base = origin.trim().replace(/\/+$/, "");
  const paths = [
    ...STATIC_PATHS,
    ...deals
      .filter((deal) => deal.status === "active")
      .map((deal) => detailPath(deal.id))
      .sort((a, b) => a.localeCompare(b)),
  ];
  const urls = paths.map((path) => `  <url><loc>${xmlEscape(`${base}${path}`)}</loc></url>`).join("\n");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`;
}

